    }
  },
  {
    json: {
      device: "Router-R5",
      ip_address: "10.10.1.5",
      bgp_status: "UP",
      interface_status: "UP",
      cpu_usage: 25,
      memory_usage: 35,
      packet_loss: 0
    }
  }
];

const metrics = $('Code in JavaScript').all();
const ai = $('AI Agent').all();

return metrics.map((m, i) => {
  const d = m.json;
  const a = (ai[i] && ai[i].json && ai[i].json.output) ? ai[i].json.output : {};

  // Deterministic health score out of 100 (reliable, not AI-guessed)
  let score = 100;
  if (d.bgp_status === 'DOWN') score -= 30;
  if (d.interface_status === 'DOWN') score -= 30;
  if (d.cpu_usage > 90) score -= 20; else if (d.cpu_usage > 75) score -= 10;
  if (d.memory_usage > 85) score -= 10; else if (d.memory_usage > 70) score -= 5;
  if (d.packet_loss > 5) score -= 15; else if (d.packet_loss > 0) score -= 5;
  if (score < 0) score = 0;

  const state = score <= 50 ? 'Critical' : 'Healthy';

  return {
    json: {
      device: d.device,
      ip_address: d.ip_address,
      state: state,
      health_score: score,
      health_display: score + '/100',
      issue: a.issue || a.network_issue || (state === 'Critical' ? 'Degraded network metrics detected' : 'No issue detected'),
      cause: a.cause || a.root_cause || 'N/A',
      action: a.action || a.recommended_action || (state === 'Critical' ? 'Investigate device' : 'No action required')
    }
  };
});

