parameters.jsCode:
const devices = $('Score Devices').all().map(i => i.json);

let tickets = [];
try { tickets = $('Create an issue').all().map(i => i.json); } catch (e) { tickets = []; }

// Critical devices are sent to Jira in order, so match tickets by order
let ci = 0;
const rows = devices.map(d => {
  let ticket = '\u274C';
  if (d.state === 'Critical') {
    const t = tickets[ci];
    ticket = (t && t.key) ? ('\u2705 ' + t.key) : '\u2705 (created)';
    ci++;
  }
  return { device: d.device, state: d.state, health_score: d.health_display, jira_ticket: ticket };
});

let table = '| Device | State | Health Score | Jira Ticket |\n';
table += '| --- | --- | --- | --- |\n';
for (const r of rows) {
  table += '| ' + r.device + ' | ' + r.state + ' | ' + r.health_score + ' | ' + r.jira_ticket + ' |\n';
}

const criticalCount = rows.filter(r => r.state === 'Critical').length;

return [{
  json: {
    report_table: table,
    total_routers: devices.length,
    critical_routers: criticalCount,
    healthy_routers: devices.length - criticalCount,
    jira_tickets_created: tickets.length,
    timestamp: $now.toISO(),
    rows: rows
  }
}];
